import { AbstractActor, Temporal } from '@dapr/dapr';
import {
  RedisConnectionService,
  JobsLogContext,
  redisConnectionFactory,
} from '@mesx/common-lib';
import { DaprClient } from 'dapr-client';
import { IPlantOrderProcessorActor } from '../interfaces/plant-order-processor.interface';
import { ActorServiceLocator } from '../services/actor-service-locator';
import { AppLogger } from '@/common/logger/app-logger';
import { asyncSleep } from '@/common/sleep/sleep';
import { RedisConfigSDKService } from '@/config/redis/redis-sdk/redis-sdk.service';
import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';
import { DaprServiceApi } from '@/dapr/dapr-api-version.service';

export class PlantOrderProcessorActor
  extends AbstractActor
  implements IPlantOrderProcessorActor
{
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: PlantOrderProcessorActor.name,
      userId,
    };
  }

  private actorId: string;

  private isShuttingDown = false;

  private isProcessing = false;

  private readonly streamName = `order_stream:`;

  // ✅ Dedicated Redis connection service for XREAD operations
  private streamRedisService: RedisConnectionService | undefined = undefined;

  private get customLogger(): AppLogger {
    return ActorServiceLocator.getInstance().getAppLogger();
  }

  private get daprService(): DaprServiceApi {
    return ActorServiceLocator.getInstance().getDaprService();
  }

  private get redisConfigService(): RedisConfigService {
    return ActorServiceLocator.getInstance().getRedisConfigService();
  }

  private get redisConfigSdkService(): RedisConfigSDKService {
    return ActorServiceLocator.getInstance().getRedisConfigSdkService();
  }

  private get sharedDaprClient(): DaprClient {
    return ActorServiceLocator.getInstance().getDaprClient();
  }

  // ✅ NEW: Create dedicated connection service for stream operations
  private async initializeStreamRedisService(): Promise<void> {
    const context = PlantOrderProcessorActor.createLogContext(
      'initializeStreamRedisService',
      Number.parseInt(this.actorId, 10),
    );

    try {
      // ✅ Use common-lib's redisConnectionFactory to create a dedicated service
      this.streamRedisService = await redisConnectionFactory(
        this.redisConfigSdkService, // Existing RedisConfigService
        this.customLogger, // Existing AppLogger
        false, // ✅ usePool: false = single dedicated connection (not pooled)
      );

      this.customLogger.verbose(
        `✅ Initialized dedicated stream Redis service for plant ${this.actorId}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to initialize stream Redis service for plant ${this.actorId}`,
        context,
        error,
      );
      throw error;
    }
  }

  public async onActivate(): Promise<void> {
    const context = PlantOrderProcessorActor.createLogContext('onActivate');

    try {
      this.actorId = this.getActorId().getId();

      // ✅ Initialize dedicated stream connection
      await this.initializeStreamRedisService();

      await this.updateActorStatus('active');

      this.customLogger.log(
        `Actor for plant ${this.actorId} activated`,
        context,
      );

      await this.registerActorReminder(
        'PlantOrderProcessorActor',
        Temporal.Duration.from({ seconds: 0 }),
        Temporal.Duration.from({ seconds: 1800 }),
      );

      this.triggerStreamSubscription();
    } catch (error) {
      await this.updateActorStatus('inactive');
      this.customLogger.error('Error during onActivate', context, error);
    }
  }

  public async onDeactivate(): Promise<void> {
    const context = PlantOrderProcessorActor.createLogContext('onDeactivate');

    try {
      this.isShuttingDown = true;
      // 🔵 Wait with timeout (e.g., 30 seconds)
      const maxWaitMs = 30_000;
      const startTime = Date.now();

      while (this.isProcessing && Date.now() - startTime < maxWaitMs) {
        await asyncSleep(100);
      }

      if (this.isProcessing) {
        this.customLogger.warn(
          `Force shutdown after timeout for plant ${this.actorId}`,
          context,
        );
      }
      if (this.streamRedisService) {
        await this.streamRedisService.disconnect();
        this.streamRedisService = undefined;

        this.customLogger.verbose(
          `Closed dedicated stream Redis service for plant ${this.actorId}`,
          context,
        );
      }

      await this.updateActorStatus('inactive');

      this.customLogger.verbose(
        `PlantOrderProcessorActor for plant ${this.actorId} deactivated`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error during deactivation: ${error.message}`,
        context,
        error,
      );
    }
  }

  public async receiveReminder(_data: string): Promise<void> {
    const context =
      PlantOrderProcessorActor.createLogContext('receiveReminder');

    try {
      // ✅ Just update the status directly - create if doesn't exist
      await this.updateActorStatus('active', 'Reminder received');

      this.customLogger.verbose(
        `Updated lastActivity for actor ${this.actorId} via reminder`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        'Failed to update activity timestamp',
        context,
        error,
      );
    }

    this.customLogger.verbose(
      `Received reminder event ${this.actorId} ${_data}`,
      context,
    );
    this.triggerStreamSubscription();
  }

  public async triggerStreamSubscription(): Promise<void> {
    const context = PlantOrderProcessorActor.createLogContext(
      'triggerStreamSubscription',
    );
    if (this.isProcessing || this.isShuttingDown) return;
    this.isProcessing = true;
    this.subscribeToStream().catch((error) => {
      this.customLogger.error(
        `Subscription error: ${error.message}`,
        context,
        error,
      );
      this.isProcessing = false;
    });
  }

  // ✅ Helper to create watchdog timeout with cleanup capability
  private createWatchdogTimeout(
    timeoutMs: number,
    operationName: string,
  ): { timer: ReturnType<typeof setTimeout>; promise: Promise<never> } {
    const context = PlantOrderProcessorActor.createLogContext(
      'createWatchdogTimeout',
    );
    let timer: ReturnType<typeof setTimeout> | undefined;
    const promise = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        reject(new Error(`${operationName}_watchdog_timeout`));
      }, timeoutMs);
    });
    this.customLogger.verbose(
      `WatchDog timeout set for ${operationName}: ${timeoutMs}ms`,
      context,
    );
    return { promise, timer: timer as ReturnType<typeof setTimeout> };
  }

  private async subscribeToStream(): Promise<void> {
    const context =
      PlantOrderProcessorActor.createLogContext('subscribeToStream');
    const fullStreamKey = this.streamName + this.actorId;
    let lastProcessedId = '0';

    if (!this.streamRedisService) {
      throw new Error('Stream Redis service not initialized');
    }

    try {
      this.customLogger.verbose(
        `Starting stream subscription for plant ${this.actorId} on key: ${fullStreamKey}`,
        context,
      );

      while (!this.isShuttingDown && this.isProcessing) {
        // ✅ Watchdog timeouts
        const GET_CLIENT_TIMEOUT_MS = 10_000; // 10 seconds for getClient
        const XREAD_TIMEOUT_MS = 15_000; // 15 seconds for xRead

        let getClientWatchdog: ReturnType<typeof setTimeout> | undefined;
        let xReadWatchdog: ReturnType<typeof setTimeout> | undefined;

        try {
          // ✅ Watchdog for getClient() - can hang on stalled connections
          let streamClient;
          try {
            const watchdog = this.createWatchdogTimeout(
              GET_CLIENT_TIMEOUT_MS,
              'getClient',
            );
            getClientWatchdog = watchdog.timer;

            this.customLogger.verbose(
              `Acquiring stream client for plant ${this.actorId}`,
              context,
            );

            streamClient = await Promise.race([
              this.streamRedisService.getClient(),
              watchdog.promise,
            ]);

            this.customLogger.verbose(
              `Acquired stream client for plant ${this.actorId}`,
              context,
            );
          } catch (getClientError) {
            // Handle getClient watchdog timeout
            if (
              getClientError instanceof Error &&
              getClientError.message === 'getClient_watchdog_timeout'
            ) {
              this.customLogger.warn(
                `getClient timed out locally for plant ${this.actorId} — recreating dedicated stream client`,
                context,
              );

              // Recreate connection
              await this.reconnectStreamService(context);
              continue;
            }

            // Re-throw non-timeout errors
            throw getClientError;
          } finally {
            if (getClientWatchdog) {
              clearTimeout(getClientWatchdog);
              getClientWatchdog = undefined;
            }
          }

          // ✅ Watchdog for xRead()
          let xMessages;
          try {
            const watchdog = this.createWatchdogTimeout(
              XREAD_TIMEOUT_MS,
              'xRead',
            );
            xReadWatchdog = watchdog.timer;

            this.customLogger.verbose(
              `Before xRead for plant ${this.actorId}, lastId: ${lastProcessedId}`,
              context,
            );

            xMessages = await Promise.race([
              streamClient.xRead(
                [{ id: lastProcessedId, key: fullStreamKey }],
                {
                  BLOCK: 5000,
                  COUNT: 1,
                },
              ),
              watchdog.promise,
            ]);

            this.customLogger.verbose(
              `After xRead for plant ${this.actorId}, received ${xMessages?.length || 0} streams`,
              context,
            );
          } catch (xReadError) {
            // Handle xRead watchdog timeout
            if (
              xReadError instanceof Error &&
              xReadError.message === 'xRead_watchdog_timeout'
            ) {
              this.customLogger.warn(
                `xRead timed out locally for plant ${this.actorId} — recreating dedicated stream client`,
                context,
              );

              // Recreate connection
              await this.reconnectStreamService(context);
              continue;
            }

            // Re-throw non-timeout errors
            throw xReadError;
          } finally {
            if (xReadWatchdog) {
              clearTimeout(xReadWatchdog);
              xReadWatchdog = undefined;
            }
          }

          if (xMessages && xMessages.length > 0) {
            for (const xMessage of xMessages) {
              for (const message of xMessage.messages) {
                try {
                  this.customLogger.debug(
                    `Processing message ID: ${message.id} for plant ${this.actorId}`,
                    context,
                  );

                  // ✅ This uses shared pool (won't be blocked by XREAD)
                  await this.daprService.handleMessageRedis(message);

                  this.customLogger.debug(
                    `Successfully processed message ID: ${message.id}`,
                    context,
                  );
                } catch (processingError) {
                  this.customLogger.error(
                    `Failed to process message ${message.id} for plant ${this.actorId}: ${processingError.message}`,
                    context,
                    processingError,
                  );
                } finally {
                  lastProcessedId = message.id;

                  try {
                    // ✅ Get fresh client for XDEL (avoid stale client)
                    const deleteClient =
                      await this.streamRedisService.getClient();
                    await deleteClient.xDel(fullStreamKey, message.id);

                    this.customLogger.verbose(
                      `Deleted message ID: ${message.id} from key: ${fullStreamKey}`,
                      context,
                    );
                  } catch (deleteError) {
                    this.customLogger.warn(
                      `Failed to delete message ${message.id} from stream: ${deleteError.message}`,
                      context,
                    );
                  }
                }
              }
            }
          } else {
            this.customLogger.verbose(
              `No messages in stream ${fullStreamKey}, waiting...`,
              context,
            );
          }
        } catch (streamError) {
          this.customLogger.error(
            `Error reading from stream ${fullStreamKey} for plant ${this.actorId}: ${streamError.message}`,
            context,
            streamError,
          );
          await this.updateActorStatus(
            'active',
            `Error reading from stream: ${streamError.message}`,
          );
          await asyncSleep(1000);
        } finally {
          // ✅ Ensure timers are always cleaned up
          if (getClientWatchdog) {
            clearTimeout(getClientWatchdog);
          }
          if (xReadWatchdog) {
            clearTimeout(xReadWatchdog);
          }
        }
      }

      this.customLogger.verbose(
        `Stream subscription ended for plant ${this.actorId}`,
        context,
      );
      await this.updateActorStatus('inactive');
    } finally {
      this.isProcessing = false;
    }
  }

  // ✅ Helper to reconnect stream service after timeout/error
  private async reconnectStreamService(context: JobsLogContext): Promise<void> {
    // Close existing client
    try {
      if (this.streamRedisService) {
        await this.streamRedisService.disconnect();
        this.customLogger.verbose(
          `Disconnected stale stream client for plant ${this.actorId}`,
          context,
        );
      }
    } catch (disconnectError) {
      this.customLogger.warn(
        `Error disconnecting stream client for plant ${this.actorId}: ${disconnectError.message}`,
        context,
      );
    }

    // Recreate dedicated stream connection
    try {
      this.streamRedisService = await redisConnectionFactory(
        this.redisConfigSdkService,
        this.customLogger,
        false,
      );
      this.customLogger.verbose(
        `✅ Recreated dedicated stream Redis service for plant ${this.actorId}`,
        context,
      );
    } catch (recreateError) {
      this.customLogger.error(
        `Failed to recreate stream Redis service for plant ${this.actorId}`,
        context,
        recreateError,
      );
      // Wait before retrying to avoid tight loop
      await asyncSleep(5000);
    }
  }

  private async updateActorStatus(
    status: 'active' | 'inactive',
    message?: string,
  ): Promise<void> {
    const context =
      PlantOrderProcessorActor.createLogContext('updateActorStatus');

    try {
      const statusKey = `actor:status:${this.actorId}`;
      const statusData = {
        lastActivity: Date.now(),
        message: message || '',
        plant: this.actorId,
        status,
        timestamp: Date.now(),
        version: '1.0.0',
      };

      await this.sharedDaprClient.state.save(
        this.redisConfigService.redisRouter,
        [{ key: statusKey, value: statusData }],
      );

      this.customLogger.verbose(
        `Updated actor status to ${status} for plant ${this.actorId}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to update actor status: ${error.message}`,
        context,
        error,
      );
    }
  }
}

/**
 * Interface for Plant Order Processor Actor
 * Defines the contract for processing order messages for a specific plant
 */
export interface IPlantOrderProcessorActor {
  /**
   * Triggers the stream subscription for the plant
   * Ensures Redis connection and starts stream processing if not active
   */
  triggerStreamSubscription(): Promise<void>;
}

import { DaprServer } from '@dapr/dapr';
import { Logger } from '@nestjs/common';
import { ModuleRef } from '@nestjs/core';
import { ActorServiceLocator } from './services/actor-service-locator';
import { PlantOrderProcessorActor } from '@/actors/plant-order-processor/implementation/plant-order-processor.actor';
import { SubscribeResponseDto } from '@/common/subscribe/dtos/subscribe.response.dto';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { DaprServiceApi } from '@/dapr/dapr-api-version.service';

/**
 * Bootstrap function to register the Plant Order Processor Actor
 * @param moduleReference The NestJS ModuleRef for dynamic service resolution
 * @param daprServiceApi The Dapr service API instance for plant initialization
 * @param eventhubService The EventHub service for pub/sub configuration
 * @param subscribeMessageService The subscribe message service for handling subscriptions
 * @returns Promise that resolves when actor is registered
 */
export async function bootstrapPlantOrderProcessorActors(
  moduleReference: ModuleRef,
  daprServiceApi: DaprServiceApi,
  eventhubService: EventhubService,
  subscribeMessageService: SubscribeMessageService,
): Promise<void> {
  try {
    // Initialize the service locator with ModuleRef
    ActorServiceLocator.initializeWithModuleRef(moduleReference);

    const daprServer = new DaprServer();
    await daprServer.actor.init();
    await daprServer.actor.registerActor(PlantOrderProcessorActor);
    await daprServer.pubsub.subscribe(
      eventhubService.pubSubName,
      eventhubService.topicPlants,
      async (data: SubscribeResponseDto): Promise<void> => {
        await subscribeMessageService.handleMessage(data);
        await daprServiceApi.initializePlant();
      },
    );
    await daprServer.start();
    Logger.log('🎯 Actor service is ready to receive invocations');
  } catch (error) {
    Logger.error('Failed to register PlantOrderProcessorActor:', error);
    throw error;
  }
}

