import { DaprServiceApi } from '@/dapr/dapr-api-version.service';

export class ActorServiceLocator {
  private static instance: ActorServiceLocator;

  private static moduleRef: ModuleRef;

  public static getInstance(): ActorServiceLocator {
    if (!ActorServiceLocator.instance) {
      ActorServiceLocator.instance = new ActorServiceLocator();
    }
    return ActorServiceLocator.instance;
  }

  public static initializeWithModuleRef(moduleReference: ModuleRef): void {
    ActorServiceLocator.moduleRef = moduleReference;
  }

  private constructor() {}

  public getRedisConnectionService(): RedisConnectionService {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(RedisConnectionService, {
      strict: false,
    });
  }

  public getAppLogger(): AppLogger {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(AppLogger, { strict: false });
  }

  public getDaprService(): DaprServiceApi {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(DaprServiceApi, { strict: false });
  }

  public getRedisConfigService(): RedisConfigService {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(RedisConfigService, {
      strict: false,
    });
  }

  public getRedisConfigSdkService(): RedisConfigSDKService {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    return ActorServiceLocator.moduleRef.get(RedisConfigSDKService, {
      strict: false,
    });
  }

  public getDaprClient(): DaprClient {
    if (!ActorServiceLocator.moduleRef) {
      throw new Error('ActorServiceLocator not initialized with ModuleRef');
    }
    const daprService = this.getDaprService();
    return daprService.getDaprClient();
  }
}

