type NonNullDestinationType = 'pickingOrder' | 'productionOrder';

// TTL constants in seconds
const DEFAULT_TTL = 21 * 24 * 60 * 60;
const SHORT_TTL = 60 * 60;

@Injectable()
export class AggregatorService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: AggregatorService.name,
    };
  }

  /**
   * Get status from mapped data if it's PickingOrder or ProductionOrder
   * Parses status format like 'StatusBO:1146,504' and returns the last part ('504')
   * @param mappedData Mapped data (PickingOrder | ProductionOrder | Buffer)
   * @returns Status string if available, undefined otherwise
   */
  private static getStatus(mappedData: MappedOutput): string | undefined {
    // Check if the mappedData has a 'status' property (PickingOrder or ProductionOrder)
    if ('status' in mappedData && mappedData.status !== undefined) {
      const statusString = String(mappedData.status);
      // Split by comma and get the last part (e.g., 'StatusBO:1146,504' -> '504')
      const splittedValue = statusString.split(',');
      return splittedValue.at(-1)?.trim();
    }
    return undefined;
  }

  /**
   * Determine TTL based on order completion status and status field value
   * @param isCompleted Whether order is completed
   * @param orderWillBeDeleted Current orderWillBeDeleted flag
   * @param statusFromPayload Status field value from payload (e.g., '503', '504')
   * @returns TTL in seconds
   */
  private static determineTTL(
    isCompleted: boolean,
    orderWillBeDeleted: boolean,
    statusFromPayload?: string,
  ): number {
    // If already marked for deletion, keep 1 hour TTL
    if (orderWillBeDeleted) {
      return SHORT_TTL;
    }

    // If order is complete and status contains 503 or 504, use 1 hour TTL
    if (
      isCompleted &&
      statusFromPayload &&
      (statusFromPayload.includes('503') || statusFromPayload.includes('504'))
    ) {
      return SHORT_TTL;
    }

    // Default: 7 days
    return DEFAULT_TTL;
  }

  /**
   * Get cache field key from source table name
   * @param sourceTable Source table name
   * @returns Cache field key
   */
  private static getCacheFieldKey(sourceTable: string): CacheFieldKey {
    const fieldKey = SOURCE_TABLE_TO_CACHE_FIELD[sourceTable];
    if (!fieldKey) {
      throw new Error(`Unknown source table: ${sourceTable}`);
    }
    return fieldKey;
  }

  /**
   * Aggregate data from multiple source tables
   * @param cachedData Cached aggregation state
   * @returns Merged data
   */
  private static aggregateOrderData(
    cachedData: AggregationState,
  ): MappedOutput {
    const { shopOrder, pickingOrder, productionOrder } = cachedData;

    // Merge all available table data - filter out undefined values
    const result: MappedOutput = {} as MappedOutput;
    if (shopOrder) Object.assign(result, shopOrder);
    if (pickingOrder) Object.assign(result, pickingOrder);
    if (productionOrder) Object.assign(result, productionOrder);

    return result;
  }

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly orderService: OrderService,
    private readonly eventEmitter: EventEmitter2,
  ) {
    this.daprClient = new DaprClient();
  }

  /**
   * Process message with aggregation caching logic
   * Key change: Cache key no longer includes operation, orders stay in Redis permanently
   * @param plant Plant ID
   * @param message Redis message
   * @param keysValueArray Keys value array
   * @param redisStore Redis store name
   */
  public async processWithAggregation(
    plant: number,
    message: RedisMessage,
    keysValueArray: KeysValueArray,
    redisStore: string,
  ): Promise<void> {
    const context = AggregatorService.createLogContext(
      'processWithAggregation',
      plant,
    );
    const { mappedData, sourceTable, operation } = message;

    // Extract order number from keysValueArray
    const orderNumber =
      keysValueArray.shopOrderId ||
      keysValueArray.pickingOrderId ||
      keysValueArray.productionOrderId;

    // New cache key format: plant.orderNumber (no operation)
    const cacheKey = `${plant}.${orderNumber}`;

    const operationInfo = {
      name: '',
      srcLocation: 'processWithAggregation',
    };
    const operationDetails = {
      cacheKey,
      operation,
      plant,
      sourceTable,
    };

    try {
      this.customLogger.debug(
        `Processing aggregation for key: ${cacheKey}, sourceTable: ${sourceTable}, operation: ${operation}`,
        context,
      );

      operationInfo.name = 'Get state';
      const result = await execAndLog(
        this.customLogger,
        context,
        () => this.daprClient.state.get(redisStore, cacheKey),
        operationInfo,
        operationDetails,
      );

      const cachedData = result.valueOf() as AggregationState | null;

      // Route to appropriate handler based on cache existence
      await (cachedData
        ? this.handleExistingCache(
            cacheKey,
            redisStore,
            cachedData,
            sourceTable,
            mappedData,
            message,
            operation || 'u',
            String(orderNumber),
          )
        : this.handleEmptyCache(
            cacheKey,
            redisStore,
            operation || 'u',
            sourceTable,
            mappedData,
            message,
            keysValueArray,
          ));
    } catch (error) {
      this.customLogger.error(
        `Error in processWithAggregation for ${cacheKey}: ${error.message}`,
        context,
        error.stack,
      );
    } finally {
      this.customLogger.debug(
        `End of processing aggregation for ${cacheKey} at ${Date.now()}`,
        context,
      );
    }
  }

  /**
   * Handle case when cache is empty (new order)
   * @param cacheKey Cache key
   * @param redisStore Redis store name
   * @param operation CDC operation
   * @param sourceTable Source table name
   * @param mappedData Mapped data
   * @param message Full message
   * @param keysValueArray Keys value array
   */
  private async handleEmptyCache(
    cacheKey: string,
    redisStore: string,
    operation: string,
    sourceTable: string,
    mappedData: MappedOutput,
    message: RedisMessage,
    keysValueArray: KeysValueArray,
  ): Promise<void> {
    const context = AggregatorService.createLogContext('handleEmptyCache');
    this.customLogger.debug(
      `Cache empty for ${cacheKey}, operation: ${operation}`,
      context,
    );

    // For create/read operations: cache and wait for aggregation
    if (operation === 'c' || operation === 'r') {
      const cacheFieldKey = AggregatorService.getCacheFieldKey(sourceTable);

      const cacheData: AggregationState = {
        [cacheFieldKey]: mappedData,
        destinationType: message.destination
          ? { destinationType: message.destination as NonNullDestinationType }
              ?.destinationType
          : null,
        isCompleted: false,
        lastUpdated: Date.now(),
      };

      // Extract status field from mappedData
      const statusFromPayload = AggregatorService.getStatus(mappedData);
      await this.saveToCache(
        redisStore,
        cacheKey,
        cacheData,
        context,
        statusFromPayload,
      );
      this.customLogger.debug(
        `Cached new order ${cacheKey} - waiting for aggregation`,
        context,
      );
      return;
    }

    // For update operations: check database first
    if (operation === 'u') {
      const { exists, destinationType } =
        await this.orderService.checkDatabaseForOrder(
          keysValueArray,
          sourceTable,
          context,
        );

      const cacheFieldKey = AggregatorService.getCacheFieldKey(sourceTable);
      let cacheData: AggregationState;

      // Extract status field from mappedData
      const statusFromPayload = AggregatorService.getStatus(mappedData);

      if (exists && destinationType) {
        // Prepare data with order ID if not from SHOP_ORDER
        let data: MappedOutput = mappedData;
        if (sourceTable === 'SHOP_ORDER' && operation === 'u') {
          const orderNumber =
            keysValueArray.shopOrderId ||
            keysValueArray.pickingOrderId ||
            keysValueArray.productionOrderId;
          data =
            destinationType === 'pickingOrder'
              ? ({
                  ...mappedData,
                  pickingOrderId: orderNumber,
                } as MappedOutput)
              : ({
                  ...mappedData,
                  productionOrderId: orderNumber,
                } as MappedOutput);
        }

        // Order exists in DB - update it and cache as completed
        await this.persistOrderToDatabase(
          destinationType,
          data,
          operation,
          context,
        );

        cacheData = {
          completedAt: Date.now(),
          destinationType,
          isCompleted: true,
          lastUpdated: Date.now(),
        };

        this.customLogger.debug(
          `Order ${cacheKey} found in DB and cached as completed`,
          context,
        );
      } else {
        // Order doesn't exist - cache as incomplete
        cacheData = {
          [cacheFieldKey]: mappedData,
          destinationType: null,
          isCompleted: false,
          lastUpdated: Date.now(),
        };

        this.customLogger.debug(
          `Order ${cacheKey} not in DB - cached as incomplete`,
          context,
        );
      }

      await this.saveToCache(
        redisStore,
        cacheKey,
        cacheData,
        context,
        statusFromPayload,
      );
    }
  }

  /**
   * Handle case when cache exists (order being updated or aggregated)
   * @param cacheKey Cache key
   * @param redisStore Redis store name
   * @param cachedData Existing cached data
   * @param sourceTable Source table name
   * @param mappedData New mapped data
   * @param message Full message
   * @param operation CDC operation
   * @param orderNumber order number
   */
  private async handleExistingCache(
    cacheKey: string,
    redisStore: string,
    cachedData: AggregationState,
    sourceTable: string,
    mappedData: MappedOutput,
    message: RedisMessage,
    operation: string,
    orderNumber: string,
  ): Promise<void> {
    const context = AggregatorService.createLogContext('handleExistingCache');
    this.customLogger.debug(
      `Cache exists for ${cacheKey}, isCompleted: ${cachedData.isCompleted}`,
      context,
    );

    const cacheFieldKey = AggregatorService.getCacheFieldKey(sourceTable);

    // Case A: Order is completed - update cache and emit to service
    if (cachedData.isCompleted) {
      // Update the specific table data in cache
      const updatedCache = {
        ...cachedData,
        lastUpdated: Date.now(),
      };

      // Extract status field from mappedData
      const statusFromPayload = AggregatorService.getStatus(mappedData);

      // Save updated cache with status-based TTL
      await this.saveToCache(
        redisStore,
        cacheKey,
        updatedCache,
        context,
        statusFromPayload,
      );

      let data = mappedData;
      if (message.sourceTable === 'SHOP_ORDER' && operation === 'u') {
        data =
          updatedCache.destinationType === 'pickingOrder'
            ? {
                ...mappedData,
                pickingOrderId: orderNumber,
              }
            : {
                ...mappedData,
                productionOrderId: orderNumber,
              };
      }
      // Call service directly based on destination type
      if (updatedCache.destinationType) {
        await this.persistOrderToDatabase(
          updatedCache.destinationType,
          data,
          operation,
          context,
        );
      }

      this.customLogger.debug(
        `Updated completed order ${cacheKey} in cache and database`,
        context,
      );
      return;
    }

    // Case B: Order incomplete - check if same or different source table
    const hasSameTable = cachedData[cacheFieldKey] !== undefined;

    if (hasSameTable) {
      // Same table received again - just update it
      const updatedCache = {
        ...cachedData,
        [cacheFieldKey]: mappedData,
        lastUpdated: Date.now(),
      };

      // Extract status field from mappedData
      const statusFromPayload = AggregatorService.getStatus(mappedData);
      await this.saveToCache(
        redisStore,
        cacheKey,
        updatedCache,
        context,
        statusFromPayload,
      );
      this.customLogger.debug(
        `Updated same table ${sourceTable} for incomplete order ${cacheKey}`,
        context,
      );
      return;
    }

    // Case C: Different table received - complete aggregation
    await this.completeAggregation(
      cacheKey,
      redisStore,
      cachedData,
      cacheFieldKey,
      mappedData,
      message,
      operation,
    );
  }

  /**
   * Complete the aggregation by merging data and inserting to database
   * @param cacheKey Cache key
   * @param redisStore Redis store name
   * @param cachedData Existing cached data
   * @param cacheFieldKey New cache field key
   * @param mappedData New mapped data
   * @param message Full message
   * @param operation CDC operation
   */
  private async completeAggregation(
    cacheKey: string,
    redisStore: string,
    cachedData: AggregationState,
    cacheFieldKey: CacheFieldKey,
    mappedData: MappedOutput,
    message: RedisMessage,
    operation: string,
  ): Promise<void> {
    const context = AggregatorService.createLogContext('completeAggregation');
    this.customLogger.debug(
      `Completing aggregation for ${cacheKey} with ${cacheFieldKey}`,
      context,
    );

    // Add new table data to cache
    const updatedCacheWithData = {
      ...cachedData,
      [cacheFieldKey]: mappedData,
    };

    // Determine final destination type
    const destinationType = (updatedCacheWithData.destinationType ||
      message.destination) as NonNullDestinationType;

    // Aggregate all available data
    const aggregatedData =
      AggregatorService.aggregateOrderData(updatedCacheWithData);

    // Extract status field from aggregated data
    const statusFromPayload = AggregatorService.getStatus(aggregatedData);

    // Attempt to insert into database
    const insertSuccess = await this.persistOrderToDatabase(
      destinationType,
      aggregatedData,
      operation,
      context,
    );

    if (insertSuccess) {
      // Mark as completed and save to cache permanently
      const completedCache: AggregationState = {
        completedAt: Date.now(),
        destinationType,
        errorStatus: undefined,
        isCompleted: true,
        lastUpdated: Date.now(),
      };

      await this.saveToCache(
        redisStore,
        cacheKey,
        completedCache,
        context,
        statusFromPayload,
      );
      this.customLogger.debug(
        `Aggregation completed for ${cacheKey} - saved to ${destinationType}`,
        context,
      );
    } else {
      // Insert failed - keep in cache with error status
      const failedCache: AggregationState = {
        ...updatedCacheWithData,
        errorStatus: 'Database insert failed',
        lastUpdated: Date.now(),
      };

      await this.saveToCache(
        redisStore,
        cacheKey,
        failedCache,
        context,
        statusFromPayload,
      );
      this.customLogger.error(
        `Failed to insert aggregated order ${cacheKey}`,
        context,
      );
    }
  }

  /**
   * Persist order to database (insert or update)
   * @param destinationType Destination type (picking or production)
   * @param aggregatedData Aggregated data
   * @param operation Operation type ('c' for create, 'u' for update)
   * @param context Log context
   * @returns True if operation successful
   */
  private async persistOrderToDatabase(
    destinationType: NonNullDestinationType,
    aggregatedData: MappedOutput,
    operation: string,
    context: JobsLogContext,
  ): Promise<boolean> {
    try {
      const eventDestination =
        destinationType === 'pickingOrder' ? 'pickingOrder' : 'productionOrder';
      const operationLabel = operation === 'c' ? 'insert' : 'update';
      const success = await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        eventDestination,
        aggregatedData,
        operation,
      );

      if (!success) {
        this.customLogger.error(
          `Failed to ${operationLabel} ${destinationType} order via event`,
          context,
        );
        return false;
      }

      this.customLogger.debug(
        `Successfully ${operationLabel}ed ${destinationType} order`,
        context,
      );
      return true;
    } catch (error) {
      this.customLogger.error(
        `Failed to ${operation === 'c' ? 'insert' : 'update'} ${destinationType} order: ${error.message}`,
        context,
        error.stack,
      );
      return false;
    }
  }

  /**
   * Save aggregation state to Redis cache with TTL
   * @param redisStore Redis store name
   * @param cacheKey Cache key
   * @param cacheData Cache data
   * @param context Log context
   * @param statusFromPayload Status field from payload data
   */
  private async saveToCache(
    redisStore: string,
    cacheKey: string,
    cacheData: AggregationState,
    context: JobsLogContext,
    statusFromPayload?: string,
  ): Promise<void> {
    const operationInfo = {
      name: 'Save state to Redis',
      srcLocation: 'saveToCache',
    };

    // Determine if we should mark for deletion (completed order with status containing 503/504)
    const shouldMarkForDeletion =
      cacheData.isCompleted &&
      !!statusFromPayload &&
      (statusFromPayload === '503' || statusFromPayload === '504');

    // Update cache data with orderWillBeDeleted if needed
    const updatedCacheData: AggregationState = {
      ...cacheData,
      orderWillBeDeleted: cacheData.orderWillBeDeleted || shouldMarkForDeletion,
    };

    // Determine TTL based on completion status and status field
    const ttl = AggregatorService.determineTTL(
      updatedCacheData.isCompleted,
      updatedCacheData.orderWillBeDeleted || false,
      statusFromPayload,
    );

    const metadata = {
      ttlInSeconds: ttl.toString(),
    };

    this.customLogger.debug(
      `Saving to cache: TTL=${ttl}s (${ttl / 3600}h), isCompleted=${updatedCacheData.isCompleted}, status=${statusFromPayload}, orderWillBeDeleted=${updatedCacheData.orderWillBeDeleted}`,
      context,
    );

    await execAndLog(
      this.customLogger,
      context,
      () =>
        this.daprClient.state.save(redisStore, [
          {
            key: cacheKey,
            metadata,
            value: updatedCacheData,
          },
        ]),
      operationInfo,
      {
        cacheKey,
        orderWillBeDeleted: updatedCacheData.orderWillBeDeleted,
        ttl,
      },
    );
  }
}

import { MappedOutput } from '@/common/mapping/interface/mapping.model';

/**
 * Aggregation state stored in Redis for order processing
 * Key format: `${plant}.${orderNumber}`
 *
 * This cache persists permanently to enable cache-first lookups for updates
 */
export interface AggregationState {
  /**
   * Shop order data (from SHOP_ORDER table)
   * Typically arrives first with empty destination
   */
  shopOrder?: MappedOutput;

  /**
   * Picking order data (from S_PICKING_ORDER table)
   */
  pickingOrder?: MappedOutput;

  /**
   * Production order data (from S_PRODUCTION_ORDER table)
   */
  productionOrder?: MappedOutput;

  /**
   * Final destination type after aggregation completes
   * - 'picking': Order is a picking order
   * - 'production': Order is a production order
   * - null: Not yet determined (aggregation incomplete)
   */
  destinationType: 'pickingOrder' | 'productionOrder' | null;

  /**
   * Whether the order has been successfully inserted into the database
   * - true: Order exists in DB, future updates can skip DB checks
   * - false: Order is still being aggregated or failed to insert
   */
  isCompleted: boolean;

  /**
   * Timestamp of last update to this cache entry
   */
  lastUpdated: number;

  /**
   * Timestamp when the order was marked as completed
   */
  completedAt?: number;

  /**
   * Error status if database insertion failed
   * Used for debugging and retry logic
   */
  errorStatus?: string;

  /**
   * Flag indicating if order will be deleted (has TTL of 1 hour)
   * Once set to true, TTL should not be updated
   */
  orderWillBeDeleted?: boolean;
}

/**
 * Helper type for source table names
 */
export type SourceTableType =
  | 'SHOP_ORDER'
  | 'S_PICKING_ORDER'
  | 'S_PRODUCTION_ORDER';

/**
 * Helper type for cache field keys
 */
export type CacheFieldKey = 'shopOrder' | 'pickingOrder' | 'productionOrder';

/**
 * Map source table names to cache field keys
 * Using Record with explicit keys to avoid linting issues with uppercase identifiers
 */
export const SOURCE_TABLE_TO_CACHE_FIELD: Record<string, CacheFieldKey> = {
  PICKING_ORDER: 'pickingOrder' as CacheFieldKey,
  PRODUCTION_ORDER: 'productionOrder' as CacheFieldKey,
  S_PICKING_ORDER: 'pickingOrder' as CacheFieldKey,
  S_PRODUCTION_ORDER: 'productionOrder' as CacheFieldKey,
  S_SHOP_ORDER: 'shopOrder' as CacheFieldKey,
  SHOP_ORDER: 'shopOrder' as CacheFieldKey,
};

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '../logger/app-logger';

interface LogTrace {
  details?: Record<string, unknown>;
  logType: string;
  operationName: string;
  runtime: number;
  srcLocation: string;
}

/**
 * Execution function and log runtime
 * @param logger Application logger
 * @param context Job Log Context
 * @param operation Function to execute
 * @param operationInfo Function properties
 * @param operationInfo.name Function name
 * @param operationInfo.srcLocation Caller code source location
 * @param details (optional)
 * @param startTime starting time
 * @returns function output
 */
export async function execAndLog<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  operationInfo: {
    name: string;
    srcLocation: string;
  },
  details?: Record<string, unknown>,
  startTime = Date.now(),
): Promise<T> {
  const result = await operation();
  const logTrace: LogTrace = {
    details,
    logType: 'Exec trace',
    operationName: operationInfo.name,
    runtime: Date.now() - startTime,
    srcLocation: operationInfo.srcLocation,
  };
  logger.debug(JSON.stringify(logTrace), context);
  return result;
}

