import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { IngestionEventTrackingDTO } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.dto.';

@Injectable()
export class MappingService {
  private readonly mappings: Array<Mapping>;

  public constructor(
    private readonly mappingUtils: MappingUtilsService,
    private readonly customLogger: AppLogger,
  ) {
    this.mappings = this.loadMappings();
  }

  /**
   * Load mapping definition
   * @returns Array of mapping configurations loaded from the JSON file
   */
  private loadMappings(): Array<Mapping> {
    const context: JobsLogContext = {
      method: 'loadMappings',
      service: 'MappingService',
    };
    try {
      return this.mappingUtils.loadMappings(
        '../config/identifier-mapping.json',
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to load mappings: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Retrieve the mapping rules between
   * source table and target table
   * @param source source table
   * @param destination  destination table
   * @returns The mapping configuration object for the specified source and destination tables
   */
  private getMapping(source: string, destination: string): Mapping {
    const mapping = this.mappings.find(
      (f) => f.source === source && f.destination === destination,
    );

    if (!mapping) {
      throw new Error(
        `No mapping found for source '${source}' and destination '${destination}'.`,
      );
    }
    return mapping;
  }

  private processColumnMappings(
    columnMappings: Array<ColumnMapping>,
    data: CombinedDtoWithIndex,
    isWip: boolean,
    timeZone: string | undefined,
    mappedData: Record<string, string | number | boolean | Date | null>,
  ): void {
    const result = mappedData;
    for (const columnMapping of columnMappings) {
      const columnsSourceValue = data[columnMapping.columnSource];

      // Skip processing if the column source value is undefined or empty
      if (columnsSourceValue !== undefined && columnsSourceValue !== '') {
        const isTimestampField = this.mappingUtils.findFieldWithTimestamp(
          columnMapping.type,
        );

        const date = isTimestampField
          ? this.mappingUtils.convertTimestampToDate(
              Number(columnsSourceValue),
              isWip,
              timeZone,
            )
          : undefined;

        result[columnMapping.columnDestination] =
          isTimestampField && date ? date : columnsSourceValue;
      }

      if (columnsSourceValue === '') {
        result[columnMapping.columnDestination] = columnMapping.allowEmpty
          ? ''
          : null;
      }
    }
  }

  /**
   * Build target record by applying mapping data
   * @param source source table name
   * @param data raw record
   * @param listPlant List Plant
   * @returns mapped data
   */
  public mapData(
    source: string,
    data: CombinedDtoWithIndex,
    listPlant: Array<PlantsResponseDto>,
  ): {
    cacheTreatment: boolean;
    destination: string;
    ingestionEventTracking: IngestionEventTrackingDTO | undefined;
    keysValue: string;
    keysValueArray: KeysValueArray;
    mappedData: MappedOutput;
  } {
    const destination = this.getDestinationTable(source);
    const mapping = this.getMapping(source, destination);
    const cacheTreatment = this.getCacheTreatment(source);

    const keysValueArray: any = {};
    const mappedData: any = {};
    let keysValue = '';

    // Build key and fill primary key fields
    for (const key of mapping.keys) {
      const keySourceValue = data[key.keySource];
      if (keySourceValue) {
        if (!key.optional) {
          mappedData[key.keyDestination] = keySourceValue;
        }
        keysValueArray[key.keyDestination] = keySourceValue;
        keysValue += keySourceValue;
      }
    }
    const {
      __source_db: sourceDatabase,
      __source_change_lsn: sourceChangeLsn,
      __source_ts_ms: sourceTsMs,
    } = data;

    const isWip = this.mappingUtils.isWIP(sourceDatabase);
    const timeZone = mappedData['plant']
      ? this.mappingUtils.getTimeZoneForPlant(mappedData['plant'], listPlant)
      : undefined;

    if (
      Array.isArray(mapping.columnMappings) &&
      mapping.columnMappings.length > 0
    ) {
      this.processColumnMappings(
        mapping.columnMappings,
        data,
        isWip,
        timeZone,
        mappedData,
      );
    }
    const changeLastLsn = sourceChangeLsn
      ? this.mappingUtils.hexStringToNumber(sourceChangeLsn)
      : '';
    const lastTimestamp = sourceTsMs ?? 0;
    const hashKey = this.generateHash(source, keysValue, destination);
    let ingestionEventTracking: IngestionEventTrackingDTO | undefined;
    if (changeLastLsn) {
      ingestionEventTracking = {
        changeLastLsn,
        destinationTable: destination,
        hashKey,
        keys: keysValue,
        lastTimestamp,
        sourceTable: source,
      };
    }
    // Convert KeysValuse to a sage base64 string for safe use in Dapr state store
    keysValue = Buffer.from(keysValue)
      .toString('base64')
      .replaceAll('/', '_')
      .replaceAll('+', '-');
    return {
      cacheTreatment,
      destination,
      ingestionEventTracking,
      keysValue,
      keysValueArray,
      mappedData,
    };
  }

  /**
   * Identify the target table
   * @param sourceTable source table
   * @returns destination table string
   */
  public getDestinationTable(sourceTable: string): string {
    const context: JobsLogContext = {
      method: 'getDestinationTable',
      service: 'MappingService',
    };
    const mapping = this.mappings.find((m) => m.source === sourceTable);
    if (!mapping) {
      const errorMessage = `Mapping not found for source table ${sourceTable}`;
      this.customLogger.error(errorMessage, context);
      throw new Error(errorMessage);
    }

    return mapping.destination;
  }

  private getCacheTreatment(sourceTable: string): boolean {
    const context: JobsLogContext = {
      method: 'getCacheTreatment',
      service: 'MappingService',
    };
    const mapping = this.mappings.find((m) => m.source === sourceTable);
    if (!mapping) {
      Object.assign(context, {
        method: 'getCacheTreatment',
        object: sourceTable,
      });
      const errorMessage = `Mapping not found for source table ${sourceTable}`;
      this.customLogger.error(errorMessage, context);
      throw new Error(errorMessage);
    }

    return mapping.cacheTreatment;
  }

  private generateHash(
    sourceTable: string,
    keys: string,
    destinationTable = '',
  ): string {
    const context: JobsLogContext = {
      method: 'generateHash',
      service: 'MappingService',
    };
    try {
      const destinationTableValue = destinationTable ?? '';
      return crypto
        .createHash('sha256')
        .update(`${sourceTable}:${keys}:${destinationTableValue}`)
        .digest('hex');
    } catch (error) {
      this.customLogger.error(
        `error when generation the hash key ${error}`,
        context,
        error.stack,
      );
      return '';
    }
  }
}

import { PickingOrder } from '@/modules/picking-order/picking-order.entity';
import { ProductionOrder } from '@/modules/production-order/production-order.entity';

/**
 * Extracts the second value from comma-separated strings in specified columns
 * @param payload - Payload Picking order or Production Order
 * @param columns - Columns of Picking order or Production Order to process
 * @returns - Picking order or Production Order with formatted columns
 */
export function substring(
  payload: PickingOrder | ProductionOrder,
  ...columns: Array<string>
): PickingOrder | ProductionOrder {
  const reformattedPayload = { ...payload };

  for (const column of columns) {
    if (reformattedPayload[column]) {
      const splittedValue = String(reformattedPayload[column]).split(',');

      // If there are at least 2 values, take the second one
      if (splittedValue.length >= 2) {
        reformattedPayload[column] = splittedValue[1].trim();
      }
    } else if (reformattedPayload[column] === null) {
      reformattedPayload[column] = ''; // In normal flow and configuration we should not have null but to avoid issues when exceptions occur, consider empty ''
    }
  }

  return reformattedPayload;
}

