/**
 * Get Plant List
 * @param logger Application logger
 * @param daprClient DAPR client
 * @param subscribeMessageService to receive plant update
 * @param redisStore Redis Store
 * @param redisPlantKey redis key
 * @returns plant list
 */
export async function getListPlant(
  logger: AppLogger,
  daprClient: DaprClient,
  subscribeMessageService: SubscribeMessageService,
  redisStore: string,
  redisPlantKey: string,
): Promise<Array<PlantsResponseDto>> {
  const context: JobsLogContext = {
    method: 'getListPlant',
    service: 'getListPlant',
  };
  try {
    logger.debug('Initialize Plant List', context);

    const redisData = await daprClient.state.get(redisStore, redisPlantKey);
    let plantList: Array<PlantsResponseDto>;

    if (redisData.valueOf()) {
      // Get plant list from Redis
      [plantList] = Object.values(redisData.valueOf());
    } else {
      // Fetch plant list and save in Redis if not found in Redis
      plantList = await subscribeMessageService.fetchPlant();
      await subscribeMessageService.savePlantsInRedis(plantList);
    }
    return plantList;
  } catch (error) {
    logger.error(
      `Error Getting list Plant : ${error.message}`,
      context,
      error.stack,
    );
    throw new HttpException(
      `error in Getting list Plant ${error}`,
      HttpStatus.BAD_REQUEST,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AppLogger } from '@/common/logger/app-logger';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';

/**
 * Emit Event
 * @param logger App logger
 * @param context Job Log Context
 * @param eventEmitter to trigger sql operation
 * @param destinationService - The destination service name
 * @param data - The mapped data
 * @param operation - The operation type (e.g., 'c' for create, 'u' for update)
 * @returns Promise<boolean> - true if operation succeeded, false otherwise
 */
export async function emitSqlEvent(
  logger: AppLogger,
  context: JobsLogContext,
  eventEmitter: EventEmitter2,
  destinationService: string,
  data: MappedOutput,
  operation: string,
): Promise<boolean> {
  const eventName = `${destinationService}.${operation}`; // TableDestination.operation
  logger.debug(
    `destinationService = ${destinationService}, eventName = ${eventName}, completedData = ${JSON.stringify(data)}`,
    context,
  );

  try {
    const results = await eventEmitter.emitAsync(eventName, data);

    // Check if any listener returned false (failure)
    const hasFailure = results.includes(false);

    if (hasFailure) {
      logger.error(
        `Event ${eventName} had failures from listeners completedData = ${JSON.stringify(data)} `,
        context,
      );
      return false;
    }

    logger.debug(`Event ${eventName} completed successfully`, context);
    return true;
  } catch (error) {
    logger.error(
      `Failed to emit event ${eventName}: ${error.message}, completedData = ${JSON.stringify(data)}`,
      context,
      error.stack,
    );
    return false;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { DaprClient } from 'dapr-client';
import { KeyValueType } from 'dapr-client/types/KeyValue.type';

import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';

/**
 * Update the cache with FIFO principle
 * @param logger - Application logger
 * @param daprClient - Dapr client for State call
 * @param redisStoreName - Redis store name for state call
 * @param key - The cache key
 * @param currentState - The current state
 * @param newRecord - The new record to add to the cache
 * @param newRecord.mappedData - The mapped data
 * @param newRecord.keysValue - The keys value
 * @param newRecord.destination - The destination
 * @param newRecord.sourceTable - The source table
 * @returns void
 */
export async function appendAndSaveToCache(
  logger: AppLogger,
  daprClient: DaprClient,
  redisStoreName: string,
  key: string,
  currentState: string | KeyValueType,
  newRecord: {
    destination: string;
    keysValue: string;
    mappedData: MappedOutput;
    sourceTable: string;
  },
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCache',
    service: 'appendAndSaveToCache',
  };
  try {
    const oldCachedData = currentState.valueOf()
      ? Object.values(currentState.valueOf())
      : [];
    const dataToCache = {
      key,
      value: [...oldCachedData, newRecord],
    };

    if (currentState.valueOf()) {
      logger.debug(`Updating state ${key} `, context);
    } else {
      logger.debug(
        `State ${key} doesn't exist caching ${JSON.stringify(dataToCache)}`,
        context,
      );
    }

    // Store the data in redis using FIFO principe
    await execAndLog(
      logger,
      context,
      () => daprClient.state.save(redisStoreName, [dataToCache]),
      {
        name: 'Save state record in cache',
        srcLocation: 'appendAndSaveToCache',
      },
      {
        key,
      },
    );
  } catch (error) {
    logger.error(
      `Failed to append and save to cache ${key}: ${error.message}`,
      error.stack,
    );
  }
}

