import { bootstrapPlantOrderProcessorActors } from '@/actors/plant-order-processor/plant-order-processor-actor.bootstrap';
import { AppModule } from '@/app.module';

/**
 * Bootstrap function to initialize the application
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });
  const initApp = await app.init();
  const moduleReference = initApp.get(ModuleRef);
  const daprService = initApp.get(DaprServiceApi);
  const eventhubService = initApp.get(EventhubService);
  const subscribeMessageService = initApp.get(SubscribeMessageService);

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  // Bootstrap the plant order processor actors
  await bootstrapPlantOrderProcessorActors(
    moduleReference,
    daprService,
    eventhubService,
    subscribeMessageService,
  );
}

bootstrap();

