import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class BufferService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: BufferService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(Buffer)
    private readonly bufferRepo: Repository<Buffer>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('buffer.u')
  private async updateByOrderIdAndPlant(payload: Buffer): Promise<void> {
    const context = BufferService.createLogContext(
      'updateByOrderIdAndPlant',
      payload?.plant,
      payload?.orderId,
    );
    const { orderId, plant, neoStatus } = payload;
    const operationInfo = {
      name: '',
      srcLocation: 'buffer.u',
    };

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    try {
      // Update the entity
      operationInfo.name = 'Update buffer (SQL)';
      if (neoStatus) {
        const result = await execAndLog(
          this.customLogger,
          context,
          () => this.bufferRepo.update({ orderId, plant }, { neoStatus }),
          operationInfo,
        );

        if (result.affected === 0) {
          return undefined;
        }
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating order: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }
}

