      'updateByProductionIdAndPlant',
      payload?.plant,
      payload?.productionOrderId,
    );

    const operationInfo = {
      name: 'Update ProductionOrder (SQL)',
      srcLocation: 'productionOrder.u',
    };

    if (!payload) {
      this.customLogger.error(`payload is empty${payload}`, context);
      return false;
    }

    const { productionOrderId, plant } = payload;

    try {
      const { ...productionOrderData } = payload;
      const reformattedPayload = substring(
        productionOrderData,
        'material',
        'workcenter',
        'status',
      );

      // Update the entity with the reformatted payload
      const result = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.productionRepository.update(
            { plant, productionOrderId },
            reformattedPayload,
          ),
        operationInfo,
        { reformattedPayload },
      );

      if (result.affected === 0) {
        this.customLogger.warn(
          `Update affected 0 rows for production order ${productionOrderId}`,
          context,
        );
        return false;
      }

      // Update related WK
      await this.updateRelatedPickingOrder(plant, productionOrderId);

      return true;
    } catch (error) {
      this.customLogger.error(
        `Error updating production order: ${error.message}`,
        context,
        error.stack,
      );
      return false;
    }
  }

  @OnEvent('productionOrder.r')
  private async readSnapshot(payload: ProductionOrder): Promise<boolean> {
    const context = ProductionOrderService.createLogContext(
      'updateByProductionIdAndPlant',
      payload?.plant,
      payload?.productionOrderId,
    );
    if (!payload) {
      this.customLogger.error(`payload is empty${payload}`, context);
      return false;
    }

    const operationInfo = {
      name: 'ProductionOrder readSnapshot (SQL)',
      srcLocation: 'productionOrder.r readSnapshot',
    };

    try {
      const { ...productionOrderData } = payload;

      const reformattedPayload = substring(
        productionOrderData,
        'material',
        'workcenter',
        'status',
      );
      const { plant, productionOrderId, ...productionReforamttedPayload } =
        reformattedPayload;

      const transactionPromise = this.productionRepository.manager.transaction(
        async (transactionalEntityManager) => {
          // Find the existing entity
          let productionOrder = await transactionalEntityManager.findOne(
            ProductionOrder,
            {
              where: {
                plant: productionOrderData.plant,
                productionOrderId: productionOrderData.productionOrderId,
              },
            },
          );
          if (productionOrder) {
            // Update the entity's fields
            Object.assign(productionOrder, productionReforamttedPayload);
            this.customLogger.debug(
              `Production Order ${payload?.productionOrderId} with Plant ID ${plant} is founded`,
              context,
            );
          } else {
            this.customLogger.debug(
              `Production Order ${payload?.productionOrderId} with Plant ID ${plant} is not found and will be inserte`,
              context,
            );
            // Create a new entity
            productionOrder = transactionalEntityManager.create(
              ProductionOrder,
              {
                plant: productionOrderData.plant,
                productionOrderId: productionOrderData.productionOrderId,
                ...productionReforamttedPayload,
              },
            );
          }

          // Save the entity (inserts if new, updates if existing)
          await transactionalEntityManager.save(productionOrder);
          this.customLogger.debug(
            `Successfully upserted Production Order ${payload?.productionOrderId} and Plant ID ${plant}`,
            context,
          );
        },
      );

      await execAndLog(
        this.customLogger,
        context,
        () => transactionPromise,
        operationInfo,
        {
          productionOrderId,
        },
      );

      return true;
    } catch (error) {
      this.customLogger.error(
        `Error upserting Production Order: ${error.message}`,
        context,
        error.stack,
      );
      return false;
    }
  }

  private async updateRelatedPickingOrder(
    plant: number,
    productionOrderId: string,
  ): Promise<void> {
    const order = await this.productionRepository.findOne({
      where: { plant, productionOrderId },
    });

    if (!order) return;

    const relatedWK = order.relatedOrder ?? '';

    if (relatedWK) {
      const hasStatus502 = await this.productionRepository.exists({
        where: { plant, relatedOrder: relatedWK, status: '502' },
      });

      const pickingRepository =
        this.productionRepository.manager.getRepository(PickingOrder);
      await pickingRepository.update(
        {
          containsHoldChildren: !hasStatus502,
          pickingOrderId: relatedWK,
          plant,
        }, // Criteria
        { containsHoldChildren: hasStatus502 }, // Update payload
      );
    }
  }
}

