export interface OrderResult {
  pickingOrderId?: string;
  productionOrderId?: string;
  orderId?: string;
  source_table: string;
}

import { JobsLogContext } from '@mesx/common-lib';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { OrderResult } from './order.interface';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { KeysValueArray } from '@/common/mapping/interface/mapping.model';
import { PickingOrder } from '@/modules/picking-order/picking-order.entity';
import { ProductionOrder } from '@/modules/production-order/production-order.entity';

type DestinationType = 'pickingOrder' | 'productionOrder' | null;

@Injectable()
export class OrderService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: OrderService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(PickingOrder)
    private readonly pickingRepository: Repository<PickingOrder>,
    @InjectRepository(ProductionOrder)
    private readonly productionRepository: Repository<ProductionOrder>,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Finds an order based on provided payload parameters.
   * Returns the first matching order from either the picking or production table.
   * @param payload - The payload containing order identifiers and plant information.
   * @returns The first matching order result or undefined if no match is found.
   */
  public async findOrder(
    payload: KeysValueArray,
  ): Promise<OrderResult | undefined> {
    const { shopOrderId, pickingOrderId, productionOrderId, plant } = payload;
    let pickingOrderIdQuery: string = pickingOrderId
      ? String(pickingOrderId)
      : '';
    let productionOrderIdQuery: string = productionOrderId
      ? String(productionOrderId)
      : '';

    if (shopOrderId) {
      pickingOrderIdQuery = String(shopOrderId);
      productionOrderIdQuery = String(shopOrderId);
    }
    const context = OrderService.createLogContext('findOrder');

    try {
      const results: Array<OrderResult> | undefined =
        await this.pickingRepository.query(
          `
        SELECT TOP 1 picking_order_id AS orderId, 'pickingOrder' AS source_table
        FROM picking_order
        WHERE plant = @0 AND picking_order_id = @1
        UNION ALL
        SELECT TOP 1 production_order_id AS orderId, 'productionOrder' AS source_table
        FROM production_order
        WHERE plant = @0 AND production_order_id = @2;
        `,
          [plant, pickingOrderIdQuery, productionOrderIdQuery],
        );

      if (results) {
        if (!results?.length) {
          return undefined;
        }
        const result: OrderResult | undefined = results[0];
        switch (result.source_table) {
          case 'pickingOrder': {
            result.pickingOrderId = result.orderId;
            break;
          }
          case 'productionOrder': {
            result.productionOrderId = result.orderId;
            break;
          }
          default: {
            this.customLogger.warn(
              `Unexpected source_table: ${result.source_table}`,
              context,
            );
          }
        }
        result.orderId = undefined;
        return result;
      }
      return undefined;
    } catch (error) {
      throw new HttpException(
        `Union Query get Shop Order Failed${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
  }

  /**
   * Check database for order existence (fallback for update operations)
   * Different source tables use different query strategies:
   * - PICKING_ORDER: Query only picking_order table
   * - PRODUCTION_ORDER: Query only production_order table
   * - SHOP_ORDER: Query both tables with UNION
   * @param keysValueArray Keys value array
   * @param sourceTable Source table
   * @param context Log context
   * @returns Object with exists flag and destination type
   */
  public async checkDatabaseForOrder(
    keysValueArray: KeysValueArray,
    sourceTable: string,
    context: JobsLogContext,
  ): Promise<{
    destinationType: DestinationType;
    exists: boolean;
  }> {
    const operationInfo = {
      name: 'Find Order in Database',
      srcLocation: 'checkDatabaseForOrder',
    };

    try {
      let orderExists = false;
      let destinationType: DestinationType = null;

      switch (sourceTable) {
        case 'PICKING_ORDER': {
          operationInfo.name = 'Find Picking Order in Database';
          const pickingOrderId =
            keysValueArray.pickingOrderId || keysValueArray.shopOrderId;

          const result = await execAndLog(
            this.customLogger,
            context,
            () =>
              this.pickingRepository.findOne({
                where: {
                  pickingOrderId: String(pickingOrderId),
                  plant: Number(keysValueArray.plant),
                },
              }),
            operationInfo,
            { pickingOrderId, plant: keysValueArray.plant },
          );

          if (result) {
            orderExists = true;
            destinationType = 'pickingOrder';
            this.customLogger.debug(
              `Picking order found in DB: ${pickingOrderId}`,
              context,
            );
          }
          break;
        }
        case 'PRODUCTION_ORDER': {
          operationInfo.name = 'Find Production Order in Database';
          const productionOrderId =
            keysValueArray.productionOrderId || keysValueArray.shopOrderId;

          const result = await execAndLog(
            this.customLogger,
            context,
            () =>
              this.productionRepository.findOne({
                where: {
                  plant: Number(keysValueArray.plant),
                  productionOrderId: String(productionOrderId),
                },
              }),
            operationInfo,
            { plant: keysValueArray.plant, productionOrderId },
          );

          if (result) {
            orderExists = true;
            destinationType = 'productionOrder';
            this.customLogger.debug(
              `Production order found in DB: ${productionOrderId}`,
              context,
            );
          }
          break;
        }
        default: {
          operationInfo.name = 'Find Order in Both Tables';
          const resultOrder = await execAndLog(
            this.customLogger,
            context,
            () => this.findOrder(keysValueArray),
            operationInfo,
            { keysValueArray },
          );

          if (resultOrder) {
            orderExists = true;
            destinationType = resultOrder.pickingOrderId
              ? 'pickingOrder'
              : 'productionOrder';
            this.customLogger.debug(
              `Order found in DB: ${JSON.stringify(resultOrder)}`,
              context,
            );
          }
          break;
        }
      }

      return { destinationType, exists: orderExists };
    } catch (error) {
      this.customLogger.error(
        `Error checking database: ${error.message}`,
        context,
        error.stack,
      );
      return { destinationType: null, exists: false };
    }
  }
}

